function get_docinfo(frm) {
	if (frm.get_docinfo) return frm.get_docinfo() || {};
	const docinfo_by_doctype = frappe.model.docinfo && frappe.model.docinfo[frm.doctype];
	return (docinfo_by_doctype && docinfo_by_doctype[frm.docname]) || {};
}

function normalize_docinfo_object(value) {
	if (Array.isArray(value)) {
		return value
			.map((item) => normalize_docinfo_object(item))
			.sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)));
	}

	if (value && typeof value === "object") {
		const out = {};
		Object.keys(value)
			.sort()
			.forEach((key) => {
				out[key] = normalize_docinfo_object(value[key]);
			});
		return out;
	}

	return value === undefined ? null : value;
}

function get_docinfo_keys(cfg) {
	return Array.isArray(cfg.watch_docinfo_keys) ? cfg.watch_docinfo_keys.filter(Boolean) : [];
}

function snapshot_docinfo(frm, state, docinfo) {
	const source = docinfo || get_docinfo(frm);
	const out = {};

	get_docinfo_keys(state.cfg).forEach((key) => {
		out[key] = normalize_docinfo_object(source[key]);
	});

	return out;
}

function peek_changed_docinfo_keys(state, docinfo) {
	const previous = state.docinfo_values || {};
	const current = snapshot_docinfo(null, state, docinfo);
	const changed = [];

	get_docinfo_keys(state.cfg).forEach((key) => {
		if (!equal(previous[key], current[key])) changed.push(key);
	});

	return changed;
}

function commit_docinfo_snapshot(state, docinfo) {
	state.docinfo_values = snapshot_docinfo(null, state, docinfo);
}

function get_changed_docinfo_keys(frm, state, docinfo) {
	const changed = peek_changed_docinfo_keys(state, docinfo);
	if (changed.length) {
		commit_docinfo_snapshot(state, docinfo);
	}
	return changed;
}

function mark_docinfo_self_change(state, keys) {
	const expires_at = Date.now() + Number(state.cfg.docinfo_self_change_suppress_ms || 0);
	if (!expires_at) return;

	state.docinfo_self_changes = state.docinfo_self_changes || {};
	keys.forEach((key) => {
		state.docinfo_self_changes[key] = expires_at;
	});
}

function filter_self_docinfo_changes(state, changed_keys) {
	const now = Date.now();
	const self_changes = state.docinfo_self_changes || {};

	return changed_keys.filter((key) => {
		if (!self_changes[key]) return true;
		if (self_changes[key] < now) {
			delete self_changes[key];
			return true;
		}

		delete self_changes[key];
		return false;
	});
}

function init_docinfo_self_change_markers(frm, state) {
	const watched_keys = get_docinfo_keys(state.cfg);
	if (!watched_keys.length || state.docinfo_self_change_markers_ready) return;
	state.docinfo_self_change_markers_ready = true;

	if (watched_keys.includes("assignments") && frm.assign_to && frm.assign_to.parent) {
		frm.assign_to.parent.on("click.dinext_fcm_docinfo_self_change", () => {
			mark_docinfo_self_change(state, ["assignments"]);
		});
	}

	if (watched_keys.includes("attachments") && frm.attachments && frm.attachments.parent) {
		frm.attachments.parent.on("click.dinext_fcm_docinfo_self_change", () => {
			mark_docinfo_self_change(state, ["attachments"]);
		});
	}

	if (watched_keys.includes("shared") && frm.shared && frm.shared.parent) {
		frm.shared.parent.on("click.dinext_fcm_docinfo_self_change", () => {
			mark_docinfo_self_change(state, ["shared"]);
		});
	}
}

function fetch_docinfo(frm) {
	return new Promise((resolve, reject) => {
		frappe.call({
			method: "frappe.desk.form.load.get_docinfo",
			args: {
				doctype: frm.doctype,
				name: frm.docname,
			},
			callback(r) {
				resolve(r && r.docinfo);
			},
			error: reject,
		});
	});
}

function refresh_watched_docinfo_blocks(frm, changed_keys) {
	if (changed_keys.includes("assignments") && frm.assign_to && frm.assign_to.refresh) {
		frm.assign_to.refresh();
	}
	if (changed_keys.includes("attachments") && frm.attachments && frm.attachments.refresh) {
		frm.attachments.refresh();
	}
	if (changed_keys.includes("shared") && frm.shared && frm.shared.refresh) {
		frm.shared.refresh();
	}
}

function apply_docinfo_changes(frm, state, docinfo, opts) {
	opts = opts || {};
	const changed_keys = peek_changed_docinfo_keys(state, docinfo);
	if (!changed_keys.length) return [];

	commit_docinfo_snapshot(state, docinfo);

	const visible_changed_keys = filter_self_docinfo_changes(state, changed_keys);
	const silent_startup = is_startup_warmup_active(state) || !state.startup_docinfo_baseline_ready;
	if (!silent_startup) {
		state.startup_docinfo_baseline_ready = true;
	}
	if (!opts.silent && !silent_startup) {
		show_docinfo_alert(visible_changed_keys, state.cfg);
	}

	refresh_watched_docinfo_blocks(frm, changed_keys);
	fcm_debug(state, "docinfo_apply", {
		doc: fcm_doc_label(frm),
		changed_keys,
		visible_changed_keys,
		silent_startup,
		opts,
	});
	return changed_keys;
}

function check_docinfo_changes(frm, state, opts) {
	state = state || get_state(frm);
	opts = opts || {};

	if (!get_docinfo_keys(state.cfg).length || !is_merge_ready(state)) {
		fcm_debug(state, "docinfo_poll_skipped", {
			doc: fcm_doc_label(frm),
			reason: !get_docinfo_keys(state.cfg).length ? "no_watched_keys" : "merge_not_ready",
		});
		return Promise.resolve([]);
	}

	return fetch_docinfo(frm)
		.then((docinfo) => {
			if (!docinfo) return [];
			return apply_docinfo_changes(frm, state, docinfo, opts);
		})
		.catch(() => []);
}

function refresh_docinfo(frm, state, opts) {
	return check_docinfo_changes(frm, state, opts);
}

function init_docinfo_polling(frm, state) {
	if (!state.cfg.refresh_docinfo_on_server_apply && !get_docinfo_keys(state.cfg).length) return;

	const interval = Number(state.cfg.poll_server_changes_interval_ms || 0);
	if (!interval || interval < 1000) return;

	if (state.docinfo_poll_timer) {
		clearInterval(state.docinfo_poll_timer);
	}

	const bound_doctype = frm.doctype;
	const bound_docname = frm.docname;

	state.docinfo_poll_timer = setInterval(() => {
		const current = cur_frm;
		if (!current || current.doctype !== bound_doctype || current.docname !== bound_docname) return;
		check_docinfo_changes(current, get_state(current));
	}, interval);
}

const FormDocInfoWatcher = {
	apply_docinfo_changes,
	check_docinfo_changes,
	commit_docinfo_snapshot,
	fetch_docinfo,
	filter_self_docinfo_changes,
	get_changed_docinfo_keys,
	get_docinfo,
	get_docinfo_keys,
	init_docinfo_polling,
	init_docinfo_self_change_markers,
	mark_docinfo_self_change,
	normalize_docinfo_object,
	peek_changed_docinfo_keys,
	refresh_docinfo,
	refresh_watched_docinfo_blocks,
	snapshot_docinfo,
};


// Source: dinext_common/public/js/form_conflict_merge/startup.js
function is_startup_warmup_active(state) {
	return Boolean(state.startup_warmup_until && Date.now() < state.startup_warmup_until);
}

function is_merge_ready(state) {
	if (!state || !state.installed) return false;
	if (Number(state.cfg.startup_warmup_ms || 0) > 0 && !state.startup_baseline_ready) return false;
	return true;
}

function get_form_wrapper(frm) {
	if (!frm.wrapper) return null;
	return frm.wrapper.on ? frm.wrapper : $(frm.wrapper);
}

function bind_startup_user_touch_marker(frm, state) {
	const $wrapper = get_form_wrapper(frm);
	if (!$wrapper || !$wrapper.on || state.startup_user_touch_marker_ready) return;
	state.startup_user_touch_marker_ready = true;

	$wrapper.on(
		"focusin.dinext_fcm_startup_touch input.dinext_fcm_startup_touch change.dinext_fcm_startup_touch keydown.dinext_fcm_startup_touch",
		(event) => {
			const original_event = event && event.originalEvent;
			if (!original_event || original_event.isTrusted === false) return;
			if (is_startup_warmup_active(state)) state.startup_user_touched = true;
		}
	);
}

function finish_startup_warmup(frm, state) {
	const current = cur_frm;
	if (!current || current.doctype !== frm.doctype || current.docname !== frm.docname) return;

	refresh_initial(frm);
	state.docinfo_values = snapshot_docinfo(frm, state);
	state.startup_docinfo_baseline_ready = true;
	state.startup_baseline_ready = true;
	state.startup_warmup_until = 0;

	if (!state.startup_user_touched) {
		mark_clean(frm);
	}

	fcm_debug(state, "warmup_finish", {
		doc: fcm_doc_label(frm),
		startup_user_touched: state.startup_user_touched,
	});
	fcm_debug_state_snapshot(state, frm, "warmup_finish_snapshot");
	fcm_debug_local_drift(state, frm, "warmup_finish_drift");

	start_deferred_services(frm, state);
}

function start_startup_warmup(frm, state) {
	const warmup_ms = Number(state.cfg.startup_warmup_ms || 0);
	state.startup_user_touched = false;
	state.startup_docinfo_baseline_ready = false;

	if (state.startup_warmup_timer) {
		clearTimeout(state.startup_warmup_timer);
		state.startup_warmup_timer = null;
	}

	if (!warmup_ms) {
		state.startup_warmup_until = 0;
		state.startup_docinfo_baseline_ready = true;
		state.startup_baseline_ready = true;
		if (!state.initial_values) refresh_initial(frm);
		start_deferred_services(frm, state);
		return;
	}

	state.startup_baseline_ready = false;

	state.startup_warmup_until = Date.now() + warmup_ms;
	bind_startup_user_touch_marker(frm, state);
	fcm_debug(state, "warmup_start", {
		doc: fcm_doc_label(frm),
		warmup_ms,
		until: new Date(state.startup_warmup_until).toISOString(),
	});
	state.startup_warmup_timer = setTimeout(() => finish_startup_warmup(frm, state), warmup_ms);
}

function set_startup_value(frm, fieldname, value, opts) {
	if (!frm || !fieldname) return Promise.resolve();

	mark_local_seed(frm, fieldname, opts);

	fcm_debug(get_state(frm), "startup_value_set", {
		doc: fcm_doc_label(frm),
		fieldname,
		value: summarize_field_value(value),
		opts,
	});

	const set_value = frappe.model.set_value(
		frm.doctype,
		frm.docname,
		fieldname,
		value,
		null,
		true
	);

	return Promise.resolve(set_value).then(() => {
		frm.refresh_field(fieldname);
		return value;
	});
}

const apply_local_seed = set_startup_value;

const FormStartup = {
	apply_local_seed,
	bind_startup_user_touch_marker,
	finish_startup_warmup,
	get_form_wrapper,
	is_merge_ready,
	is_startup_warmup_active,
	set_startup_value,
	start_startup_warmup,
};


// Source: dinext_common/public/js/form_conflict_merge/merge_engine.js
function cancel_deferred_services(state) {
	if (!state) return;
	if (state.poll_timer) {
		clearInterval(state.poll_timer);
		state.poll_timer = null;
	}
	if (state.docinfo_poll_timer) {
		clearInterval(state.docinfo_poll_timer);
		state.docinfo_poll_timer = null;
	}
	if (state.startup_warmup_timer) {
		clearTimeout(state.startup_warmup_timer);
		state.startup_warmup_timer = null;
	}
	state.pollers_ready = false;
}

function cancel_bound_pollers(frm, except_key) {
	Object.keys(registry).forEach((key) => {
		if (key === except_key) return;
		const bound = registry[key];
		if (!bound || bound.frm !== frm) return;
		fcm_debug(bound, "cancel_bound_pollers", {
			doc: fcm_doc_label(frm),
			cancelled_key: key,
			active_key: except_key,
			highlighted_fields: Object.keys(bound.highlighted_fields || {}),
		});
		clear_highlights(frm, bound);
		cancel_deferred_services(bound);
		bump_sync_generation(bound);
	});
}

function cancel_pending_reload(frm) {
	if (frm.debounced_reload_doc && frm.debounced_reload_doc.cancel) {
		frm.debounced_reload_doc.cancel();
	}
}

function apply_server_changes(frm, server_doc, state, opts) {
	opts = opts || {};
	const silent_startup = opts.silent || is_startup_warmup_active(state);
	const modified_changed = Boolean(server_doc && server_doc.modified && server_doc.modified !== state.initial_modified);
	const analysis = analyze(frm, server_doc, state);
	const applied_server = analysis.server_only.slice();
	const applied_conflicts = state.cfg.conflict_policy === "server_wins" ? analysis.conflicts.slice() : [];

	fcm_debug_analysis(state, frm, analysis, {
		source: opts.source || "apply_server_changes",
		server_snapshot: snapshot(server_doc, state.fields),
		silent_startup,
		modified_changed,
		server_modified: server_doc && server_doc.modified,
		server_modified_by: server_doc && server_doc.modified_by,
	});

	applied_server.forEach((fieldname) => {
		apply_field(frm, server_doc, fieldname);
		update_initial_value(state, server_doc, fieldname);
		if (!silent_startup) highlight_field(frm, state, fieldname, "server");
	});

	applied_conflicts.forEach((fieldname) => {
		apply_field(frm, server_doc, fieldname);
		update_initial_value(state, server_doc, fieldname);
		if (!silent_startup) highlight_field(frm, state, fieldname, "conflict");
	});

	apply_modified(frm, server_doc);
	sync_matching_server_values(frm, server_doc, state);

	analysis.applied_server = applied_server;
	analysis.applied_conflicts = applied_conflicts;
	analysis.remaining_local = get_remaining_local_changes(frm, state);
	analysis.modified_changed = modified_changed;

	state.server_changed = analysis.conflicts.length > applied_conflicts.length;
	state.server_modified = server_doc.modified;
	state.server_modified_by = server_doc.modified_by;

	if (!state.server_changed) {
		state.initial_modified = server_doc.modified;
	}

	if (!analysis.remaining_local.length) {
		mark_clean(frm);
	}

	if (modified_changed && state.cfg.refresh_docinfo_on_server_apply) {
		refresh_docinfo(frm, state, { silent: silent_startup });
	}

	fcm_debug(state, "apply_server_changes_done", {
		doc: fcm_doc_label(frm),
		source: opts.source || "apply_server_changes",
		applied_server,
		applied_conflicts,
		remaining_local: analysis.remaining_local,
		silent_startup,
	});

	return analysis;
}

function handle_doc_update(data) {
	const frm = cur_frm;
	if (!frm || !frm.doc || frm.is_new() || !data) return;
	if (data.doctype !== frm.doctype || data.name !== frm.docname) return;
	if (frappe.ui.form.is_saving) return;
	if (data.modified && data.modified === frm.doc.modified) return;

	const state = get_state(frm);
	if (!state.installed) return;

	if (!is_merge_ready(state)) {
		fcm_debug(state, "doc_update_skipped", {
			doc: fcm_doc_label(frm),
			reason: "merge_not_ready",
			data,
			frm_modified: frm.doc.modified,
			initial_modified: state.initial_modified,
		});
		return;
	}

	fcm_debug(state, "doc_update", {
		doc: fcm_doc_label(frm),
		data,
		frm_modified: frm.doc.modified,
		initial_modified: state.initial_modified,
	});

	cancel_pending_reload(frm);

	state.server_changed = true;
	state.server_modified = data.modified;
	state.server_modified_by = data.modified_by;

	const silent_startup = is_startup_warmup_active(state);
	if (state.cfg.show_realtime_alert && !silent_startup) {
		show_realtime_alert(data);
	}

	if (state.cfg.apply_server_changes_on_realtime) {
		const generation = state.sync_generation;
		const bound_docname = frm.docname;
		fetch_server_doc(frm).then((server_doc) => {
			if (is_sync_stale(state, generation, frm) || frm.docname !== bound_docname) {
				fcm_debug(state, "doc_update_stale", {
					doc: fcm_doc_label(frm),
					bound_docname,
					current_docname: frm.docname,
					generation,
					sync_generation: state.sync_generation,
				});
				return;
			}
			if (!server_doc || !server_doc.modified || server_doc.modified === state.initial_modified) {
				fcm_debug(state, "doc_update_fetch_skipped", {
					doc: fcm_doc_label(frm),
					reason: !server_doc
						? "no_server_doc"
						: !server_doc.modified
							? "no_server_modified"
							: "modified_unchanged",
					server_modified: server_doc && server_doc.modified,
					initial_modified: state.initial_modified,
				});
				return;
			}
			fcm_debug_child_tables(state, frm, "doc_update_child_tables_before_apply", server_doc, {
				source: "doc_update",
			});
			const analysis = apply_server_changes(frm, server_doc, state, {
				silent: silent_startup,
				source: "doc_update",
			});
			if (state.cfg.show_applied_alert && !silent_startup) show_applied_alert(analysis);
		});
	}
}

function init_listener() {
	if (window.__dinext_form_conflict_merge_listener_ready) return;
	window.__dinext_form_conflict_merge_listener_ready = true;
	frappe.realtime.on("doc_update", handle_doc_update);
}

function check_server_changes(frm) {
	if (!frm || !frm.doc || frm.is_new()) return Promise.resolve();
	const state = get_state(frm);
	if (!state.installed) return Promise.resolve();

	if (!is_merge_ready(state)) {
		fcm_debug(state, "poll_skipped", {
			doc: fcm_doc_label(frm),
			reason: "merge_not_ready",
			startup_baseline_ready: state.startup_baseline_ready,
			startup_warmup_active: is_startup_warmup_active(state),
		});
		return Promise.resolve();
	}

	if (state.initial_modified && frm.doc.modified && state.initial_modified !== frm.doc.modified) {
		fcm_debug(
			state,
			"poll_baseline_mismatch",
			{
				doc: fcm_doc_label(frm),
				initial_modified: state.initial_modified,
				frm_modified: frm.doc.modified,
			},
			FCM_LOG_LEVELS.warn
		);
	}

	fcm_debug_local_drift(state, frm, "poll_local_drift");

	const generation = state.sync_generation;
	const bound_docname = frm.docname;

	return fetch_server_doc(frm).then((server_doc) => {
		if (is_sync_stale(state, generation, frm) || frm.docname !== bound_docname) {
			fcm_debug(state, "poll_stale", {
				doc: fcm_doc_label(frm),
				bound_docname,
				current_docname: frm.docname,
				generation,
				sync_generation: state.sync_generation,
			});
			return;
		}
		if (!server_doc || !server_doc.modified || server_doc.modified === state.initial_modified) {
			fcm_debug(state, "poll_noop", {
				doc: fcm_doc_label(frm),
				reason: !server_doc
					? "no_server_doc"
					: !server_doc.modified
						? "no_server_modified"
						: "modified_unchanged",
				server_modified: server_doc && server_doc.modified,
				initial_modified: state.initial_modified,
				frm_modified: frm.doc.modified,
			});
			return;
		}

		fcm_debug(state, "poll_detected_change", {
			doc: fcm_doc_label(frm),
			server_modified: server_doc.modified,
			initial_modified: state.initial_modified,
			frm_modified: frm.doc.modified,
			server_modified_by: server_doc.modified_by,
		});
		fcm_debug_child_tables(state, frm, "poll_child_tables_before_apply", server_doc, {
			source: "poll",
		});

		const silent_startup = is_startup_warmup_active(state);
		const analysis = apply_server_changes(frm, server_doc, state, {
			silent: silent_startup,
			source: "poll",
		});
		if (state.cfg.show_applied_alert && !silent_startup) show_applied_alert(analysis);
		return analysis;
	});
}

function init_polling(frm, state) {
	const interval = Number(state.cfg.poll_server_changes_interval_ms || 0);
	if (!interval || interval < 1000) return;

	if (state.poll_timer) {
		clearInterval(state.poll_timer);
	}

	const bound_doctype = frm.doctype;
	const bound_docname = frm.docname;

	state.poll_timer = setInterval(() => {
		const current = cur_frm;
		if (!current || current.doctype !== bound_doctype || current.docname !== bound_docname) return;
		check_server_changes(current);
	}, interval);
}

function confirm_conflicts(conflicts, cfg) {
	if (!conflicts.length) return Promise.resolve("continue");
	if (cfg.conflict_policy === "local_wins") return Promise.resolve("local_wins");
	if (cfg.conflict_policy === "server_wins") return Promise.resolve("server_wins");
	if (cfg.conflict_policy === "block") return Promise.resolve("block");

	return new Promise((resolve) => {
		const message = [
			"Документ был изменён на сервере, и часть полей конфликтует с вашими правками.",
			"",
			`Конфликтующие поля: ${conflicts.join(", ")}`,
			"",
			"Выберите, как продолжить сохранение.",
		].join("<br>");

		const dialog = new frappe.ui.Dialog({
			title: "Конфликт изменений",
			fields: [{ fieldtype: "HTML", fieldname: "message", options: message }],
			primary_action_label: "Сохранить мои значения",
			primary_action() {
				dialog.hide();
				resolve("local_wins");
			},
			secondary_action_label: "Взять значения сервера",
			secondary_action() {
				dialog.hide();
				resolve("server_wins");
			},
		});

		dialog.$wrapper.find(".modal-footer").prepend(
			$(`<button class="btn btn-default btn-sm">${__("Отменить сохранение")}</button>`).on("click", () => {
				dialog.hide();
				resolve("block");
			})
		);

		dialog.show();
	});
}

function fetch_server_doc(frm) {
	return new Promise((resolve, reject) => {
		frappe.call({
			method: "frappe.client.get",
			type: "GET",
			args: {
				doctype: frm.doctype,
				name: frm.docname,
			},
			callback(r) {
				resolve(r.message);
			},
			error: reject,
		});
	});
}

function before_save(frm) {
	if (frm.is_new()) return Promise.resolve();

	const state = get_state(frm);
	if (!state.installed) return Promise.resolve();

	fcm_debug_child_tables(state, frm, "before_save_local", null, {
		frm_modified: frm.doc.modified,
		initial_modified: state.initial_modified,
		frm_unsaved: frm.doc.__unsaved,
	});

	return fetch_server_doc(frm).then((server_doc) => {
		if (!server_doc || !server_doc.modified || server_doc.modified === state.initial_modified) {
			fcm_debug(state, "before_save_noop", {
				doc: fcm_doc_label(frm),
				reason: !server_doc
					? "no_server_doc"
					: !server_doc.modified
						? "no_server_modified"
						: "modified_unchanged",
				server_modified: server_doc && server_doc.modified,
				initial_modified: state.initial_modified,
				frm_modified: frm.doc.modified,
			});
			return;
		}

		fcm_debug_child_tables(state, frm, "before_save_server", server_doc, {
			server_modified: server_doc.modified,
			initial_modified: state.initial_modified,
			conflict_policy: state.cfg.conflict_policy,
		});

		if (state.cfg.conflict_policy === "server_wins") {
			const analysis = apply_server_changes(frm, server_doc, state);
			if (state.cfg.show_applied_alert) show_applied_alert(analysis);
			return;
		}

		const analysis = analyze(frm, server_doc, state);
		analysis.server_only.forEach((fieldname) => {
			apply_field(frm, server_doc, fieldname);
			update_initial_value(state, server_doc, fieldname);
			highlight_field(frm, state, fieldname, "server");
		});

		return confirm_conflicts(analysis.conflicts, state.cfg).then((decision) => {
			if (decision === "block") {
				frappe.validated = false;
				frappe.throw("Сохранение отменено: документ был изменён на сервере.");
			}

			if (decision === "server_wins") {
				analysis.conflicts.forEach((fieldname) => {
					apply_field(frm, server_doc, fieldname);
					update_initial_value(state, server_doc, fieldname);
					highlight_field(frm, state, fieldname, "conflict");
				});
			}

			apply_modified(frm, server_doc);
			sync_matching_server_values(frm, server_doc, state);
			state.server_changed = decision !== "server_wins" && analysis.conflicts.length > 0;
			state.initial_modified = server_doc.modified;
		});
	});
}

function start_deferred_services(frm, state) {
	if (state.pollers_ready) return;
	state.pollers_ready = true;
	fcm_debug(state, "pollers_start", {
		doc: fcm_doc_label(frm),
		poll_ms: state.cfg.poll_server_changes_interval_ms,
		watch_docinfo_keys: state.cfg.watch_docinfo_keys,
	});
	init_polling(frm, state);
	init_docinfo_polling(frm, state);
}

function install(frm, opts) {
	opts = opts || {};
	if (!frm || !frm.doctype) frappe.throw("FormConflictMerge: вызовите из onload(frm)");

	const cfg = Object.assign({}, DEFAULT_CONFIG, opts);
	const state_key = `${frm.doctype}::${frm.docname}`;
	cancel_bound_pollers(frm, state_key);
	const state = get_state(frm);
	clear_all_fcm_highlights(frm, state);
	const first_install = !state.installed;
	const new_form_instance = state.frm !== frm;
	state.cfg = cfg;
	state.fields = get_fields(frm, cfg);
	state.installed = true;
	state.frm = frm;
	state.doc_key = state_key;
	bump_sync_generation(state);

	if (new_form_instance) {
		cancel_deferred_services(state);
	}

	ensure_highlight_styles();
	const warmup_enabled = Number(cfg.startup_warmup_ms || 0) > 0;
	if (!warmup_enabled && (first_install || !state.initial_values)) {
		refresh_initial(frm);
		state.startup_baseline_ready = true;
	} else if (warmup_enabled && (first_install || new_form_instance)) {
		state.startup_baseline_ready = false;
	}
	import_pending_local_seeds(frm, state);
	if (first_install || new_form_instance) start_startup_warmup(frm, state);
	else if (!state.pollers_ready && is_merge_ready(state)) start_deferred_services(frm, state);
	state.docinfo_values = snapshot_docinfo(frm, state);
	init_docinfo_self_change_markers(frm, state);
	init_listener();

	fcm_debug(state, "install", {
		doc: fcm_doc_label(frm),
		first_install,
		new_form_instance,
		warmup_enabled,
		startup_baseline_ready: state.startup_baseline_ready,
		debug_enabled: is_fcm_debug_enabled(state),
		tracked_fields: state.fields.length,
		child_tables: state.fields.filter((fieldname) => is_child_table_field(frm, fieldname)),
		cfg: {
			conflict_policy: cfg.conflict_policy,
			poll_server_changes_interval_ms: cfg.poll_server_changes_interval_ms,
			startup_warmup_ms: cfg.startup_warmup_ms,
			watch_docinfo_keys: cfg.watch_docinfo_keys,
			debug_log: cfg.debug_log,
		},
	});

	if (is_fcm_debug_enabled(state)) {
		console.info(
			`${FCM_LOG_PREFIX} debug ON для ${fcm_doc_label(frm)}. Фильтр консоли: FCM. События: install, warmup_*, refresh_initial, poll_*, analyze, child_tables, apply_child_table, before_save_*, sync_matching_baseline, highlight, local_drift. dump: dinext_common.formConflictMerge.dump_debug_state()`
		);
		fcm_debug_state_snapshot(state, frm, "install_snapshot");
	}

	if (window.__dinext_form_conflict_merge_doctype_hooks && window.__dinext_form_conflict_merge_doctype_hooks[frm.doctype]) {
		return;
	}

	window.__dinext_form_conflict_merge_doctype_hooks = window.__dinext_form_conflict_merge_doctype_hooks || {};
	window.__dinext_form_conflict_merge_doctype_hooks[frm.doctype] = true;

	frappe.ui.form.on(frm.doctype, {
		before_save,
		after_save(frm) {
			clear_local_seeds(frm);
			refresh_initial(frm);
		},
		refresh(frm) {
			const active = get_state(frm);
			if (!active.initial_values && is_merge_ready(active)) refresh_initial(frm);
		},
	});
}

const FormMergeEngine = {
	analyze,
	apply_server_changes,
	before_save,
	cancel_deferred_services,
	cancel_pending_reload,
	check_server_changes,
	confirm_conflicts,
	fetch_server_doc,
	handle_doc_update,
	init_listener,
	init_polling,
	install,
	start_deferred_services,
};


